from dataclasses import dataclass
@dataclass(frozen=True)
class Contract:
    version: int
    shape: tuple
    dtype: str
    max_age_ms: int
OUT_V2 = Contract(2, (1, 20, 3), "float16", 50)   # 궤적 20점 × (x, y, 방향)
def check(c, msg, now_ms):
    errs = []
    if msg["version"] != c.version: errs.append(f"version {msg['version']}!={c.version}")
    if tuple(msg["shape"]) != c.shape: errs.append(f"shape {tuple(msg['shape'])}")
    if msg["dtype"] != c.dtype: errs.append(f"dtype {msg['dtype']}")
    if now_ms - msg["stamp_ms"] > c.max_age_ms: errs.append(f"age {now_ms - msg['stamp_ms']}ms")
    return errs or ["OK"]
print(check(OUT_V2, {"version": 2, "shape": [1, 20, 3], "dtype": "float16", "stamp_ms": 1000}, 1030))
print(check(OUT_V2, {"version": 3, "shape": [1, 30, 3], "dtype": "float16", "stamp_ms": 1000}, 1030))
print(check(OUT_V2, {"version": 2, "shape": [1, 20, 3], "dtype": "float32", "stamp_ms": 1000}, 1090))
# ['OK']
# ['version 3!=2', 'shape (1, 30, 3)']
# ['dtype float32', 'age 90ms']
